g.desc:
[Visualization]
name=undefined;
type=GcObject;
display=true;
backgroundColor=#000;
state=$'name'.StCode;
tag=$'name'.StCode(0x1000);
beginUpdate=function(){
if (this.tag == "4096") {
	this.isFeeding = false;
	this.backgroundColor="#FF0000";
}
else {
	if (!isNaN(this.state)){
	this.isFeeding = true;
	this.backgroundColor="#008000";
}
}
};

